import sys

d = sys.stdin.read().split()
n = int(d[0])
edges = [(int(d[1 + 3 * i]), int(d[2 + 3 * i]), int(d[3 + 3 * i])) for i in range(n - 1)]
deg = [0] * n
for u, v, w in edges:
    deg[u] += 1
    deg[v] += 1
best = None
for mask in range(1 << (n - 1)):
    comp = list(range(n))
    def find(x):
        while comp[x] != x:
            comp[x] = comp[comp[x]]
            x = comp[x]
        return x
    cost = 0
    for i, (u, v, w) in enumerate(edges):
        if mask >> i & 1:
            cost += w
        else:
            comp[find(u)] = find(v)
    cnt = {}
    ok = True
    for x in range(n):
        if deg[x] == 1:
            r = find(x)
            if r in cnt:
                ok = False
                break
            cnt[r] = 1
    if ok and (best is None or cost < best):
        best = cost
print(best)

