def gen(rng):
    def build(n, parents, wmax, shuffle_labels=True):
        perm = list(range(n))
        if shuffle_labels:
            rng.shuffle(perm)
        edges = []
        for i in range(1, n):
            a, b = perm[i], perm[parents[i]]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append((a, b, rng.randint(1, wmax)))
        rng.shuffle(edges)
        return str(n) + ("\n" if edges else "") + "\n".join(f"{a} {b} {w}" for a, b, w in edges)
    def rand_parents(n, mode):
        ps = [0] * n
        for i in range(1, n):
            if mode == "rand":
                ps[i] = rng.randrange(i)
            elif mode == "path":
                ps[i] = i - 1
            elif mode == "mix":
                ps[i] = rng.choice([i - 1, rng.randrange(i)])
            else:
                ps[i] = 0
        return ps
    tests = ["1", "2\n0 1 5", "2\n1 0 1000000000", "3\n0 1 4\n1 2 9", "3\n2 0 4\n1 0 9"]
    tests.append("5\n0 1 3\n1 2 5\n2 3 2\n1 4 4")
    tests.append("5\n0 1 7\n0 2 1\n0 3 9\n0 4 4")
    tests.append("4\n0 1 6\n1 2 2\n2 3 9")
    for n in range(4, 13):
        for mode in ("rand", "path", "mix", "star"):
            if rng.random() < 0.5:
                tests.append(build(n, rand_parents(n, mode), rng.choice([3, 10, 1000])))
    for _ in range(20):
        n = rng.randint(2, 12)
        tests.append(build(n, rand_parents(n, rng.choice(["rand", "mix"])), rng.choice([2, 6, 10 ** 9])))
    N = 50000
    # random recursive tree (shallow)
    tests.append(build(N, rand_parents(N, "rand"), 10 ** 9))
    # star
    tests.append(build(N, rand_parents(N, "star"), 10 ** 9))
    # caterpillar: spine of 4000 nodes, every other node hangs off a spine node
    sp = 4000
    ps = [0] * N
    for i in range(1, N):
        ps[i] = i - 1 if i < sp else rng.randrange(sp)
    tests.append(build(N, ps, 10 ** 9))
    # broom: path of 2500 ending in a big star, plus weights mostly large
    ps = [0] * N
    for i in range(1, N):
        ps[i] = i - 1 if i < 2500 else 2499
    tests.append(build(N, ps, 10 ** 9))
    # many long thin branches hanging off a hub (each branch up to 100 deep)
    ps = [0] * N
    for i in range(1, N):
        ps[i] = 0 if i % 100 == 1 else i - 1
    tests.append(build(N, ps, 10 ** 9))
    # long path of 5000 nodes
    tests.append(build(5001, rand_parents(5001, "path"), 10 ** 9))
    return tests

